<template><section class="rounded border border-gray-200 p-3"><div class="mb-2 flex justify-between font-bold"><span>支付明细</span><span v-if="requiredAmount !== null" :class="unpaid?'text-red-500':'text-green-600'">应收 ￥{{ Number(requiredAmount).toFixed(2) }} / 实收 ￥{{ total.toFixed(2) }}</span></div><div v-for="(pay,index) in rows" :key="pay.code" class="mb-2 rounded bg-gray-50 p-2"><div class="flex items-center gap-2"><span class="w-24">{{pay.name}}</span><el-input-number v-model="pay.amount" :min="0" :max="pay.code==='BALANCE'&&memberBalance!==null?memberBalance:undefined" :precision="2" :controls="false" class="flex-1" @change="onPayChange(index)" /></div><el-radio-group v-if="pay.code==='AGGREGATE'&&tags.length" v-model="pay.payTag" class="mt-2" size="small" @change="emitValue"><el-radio-button v-for="tag in tags" :key="tag.value" :label="tag.value">{{tag.desc}}</el-radio-button></el-radio-group></div><div v-if="requiredAmount !== null" class="text-sm font-bold"><span v-if="unpaid" class="text-red-500">还差 ￥{{ unpaid.toFixed(2) }}</span><span v-else-if="change" class="text-green-600">现金找零 ￥{{ change.toFixed(2) }}</span><span v-else class="text-green-600">支付金额已匹配</span></div></section></template>
<script setup>
import {computed,ref,watch} from 'vue'; import dictApi from '@/api/system/dict.js'
const props=defineProps({requiredAmount:{type:Number,default:null},memberBalance:{type:Number,default:null}});const emit=defineEmits(['update:payments']);const rows=ref([]),tags=ref([]);const total=computed(()=>rows.value.reduce((s,p)=>s+Number(p.amount||0),0));const cash=computed(()=>Number(rows.value.find(p=>p.code==='CASH')?.amount||0));const nonCash=computed(()=>total.value-cash.value);const unpaid=computed(()=>props.requiredAmount===null?0:Math.max(0,Number(props.requiredAmount)-total.value));const change=computed(()=>props.requiredAmount===null?0:Math.max(0,cash.value-Math.max(0,Number(props.requiredAmount)-nonCash.value)));const emitValue=()=>emit('update:payments',rows.value.filter(p=>Number(p.amount)>0).map(p=>({payMethodCode:p.code,payMethodName:p.name,payAmount:Number(p.amount),payTag:p.payTag||null})));const onPayChange=index=>{const p=rows.value[index];if(p.code==='BALANCE'&&props.memberBalance!==null)p.amount=Math.min(Number(p.amount||0),props.memberBalance);const agg=rows.value.find(x=>x.code==='AGGREGATE');if(agg&&p!==agg&&props.requiredAmount!==null){const other=rows.value.filter(x=>x!==agg).reduce((s,x)=>s+Number(x.amount||0),0);agg.amount=Math.max(0,Number(props.requiredAmount)-other)}emitValue()};const init=async()=>{const d=await dictApi.loadDict(['pos_payment_method','paySubTag']).catch(()=>({}));tags.value=d?.paySubTag||[];const methods=d?.pos_payment_method?.length?d.pos_payment_method:[{value:'AGGREGATE',desc:'聚合扫码'},{value:'CASH',desc:'现金支付'},{value:'BALANCE',desc:'会员余额'}];rows.value=methods.map(x=>({code:x.value,name:x.desc,amount:0,payTag:x.value==='AGGREGATE'?tags.value[0]?.value:null}));if(props.requiredAmount!==null)(rows.value.find(x=>x.code==='AGGREGATE')||rows.value[0]).amount=Number(props.requiredAmount);emitValue()};watch(()=>props.requiredAmount,init,{immediate:true})
</script>
